look.css:
/* Luggage tag: a cream paper tag on dark teal, a punched stub with the code, a perforation, the idea in big condensed type. */
.card { background: var(--card); color: #17302f; border-radius: 10px 10px 26px 26px; box-shadow: 0 18px 30px -16px rgba(0,0,0,.6); }
.stub { flex: 0 0 auto; padding: 22px 22px 18px; display: grid; grid-template-columns: auto 1fr; align-items: end; gap: 6px 14px;
  border-bottom: 3px dashed rgba(23,48,47,.28); background: hsl(var(--hue) 70% 62%); position: relative; }
.hole { position: absolute; top: 16px; right: 20px; width: 22px; height: 22px; border-radius: 50%; background: var(--bg); box-shadow: inset 0 0 0 4px rgba(0,0,0,.12); }
.code { font: 900 84px/0.8 var(--display); letter-spacing: -0.01em; grid-row: span 2; }
.kind { font: 600 11px var(--mono); letter-spacing: .12em; text-transform: uppercase; align-self: end; }
.body { padding: 18px 22px 22px; display: flex; flex-direction: column; gap: 10px; flex: 1; }
.from { font: 400 10px var(--mono); letter-spacing: .14em; opacity: .6; }
.body h2 { font: 700 40px/0.95 var(--display); text-transform: uppercase; margin: 0; text-wrap: balance; }
.body p { margin: 0; font: 400 16px/1.45 var(--body); color: #3d5654; }
.bars { margin-top: auto; flex: 0 0 28px; background: repeating-linear-gradient(90deg, #17302f 0 2px, transparent 2px 5px, #17302f 5px 6px, transparent 6px 10px); opacity: .7; }
.stamp { border-radius: 2px; font-family: var(--display); }
@media (max-height: 700px) { .code { font-size: 64px; } .body h2 { font-size: 32px; } }
